"""Real tests for app/tools/prodigal_genes.py -- no mocking, runs the
real prodigal CLI (apt prodigal package, present in the Docker image)."""
from app.tools.prodigal_genes import predict_genes

# A real E. coli lacZ gene fragment (start), long enough for Prodigal's
# meta-mode gene calling to find a real ORF.
LACZ_FRAGMENT = (
    ""
)


async def text_of(result):
    return result["content"][0]["text"]


async def test_happy_path_predicts_real_genes():
    result = await predict_genes.handler({"sequence": LACZ_FRAGMENT})
    text = await text_of(result)
    assert "Prodigal" in text
    assert "predicted gene" in text


async def test_too_short_sequence_reports_error():
    result = await predict_genes.handler({"sequence": "ATGC" * 10})
    text = await text_of(result)
    assert "at least 200bp" in text


async def test_invalid_characters_report_error():
    result = await predict_genes.handler({"sequence": "ATGCXYZ" * 40})
    text = await text_of(result)
    assert "only A/C/G/T/N" in text
